"""Tables for the note, from OutCLAUDE/sweep_MIRROR.json. Generated by Claude Opus 5.5 -- 01/10/2026."""
import json, os, sys
import numpy as np
HERE = os.path.dirname(os.path.abspath(__file__))
res = json.load(open(os.path.join(HERE, 'OutCLAUDE', 'sweep_MIRROR.json')))
LAT = ['sq5', 'sq9', 'tri']
def get(lat, N, co, sg):
    for r in res:
        if (r['lattice'], r['N'], r['co_tag'], r['sig_tag']) == (lat, N, co, sg):
            return r
def trip(r, k, key='eps_ang'):            # value at t = k round trips (4 samples per trip)
    return r[key][4 * k]
def slope(r):                              # log-log slope of eps_ang(trip k), k = 1..10
    k = np.arange(1, 11); e = np.array([trip(r, i) for i in k])
    return np.polyfit(np.log(k), np.log(e), 1)[0]
Ns = sorted({r['N'] for r in res})
f = lambda x: f'{x:.1e}'
for sg in ['3', 'f0.025']:
    print(f'\n### sigma = {sg}, Co = 0.5: eps_ang free-space (t=T/4) | trip 1 | 2 | 5 | 10 | log-log slope | eps_0 trip 1 | 10')
    print('| lattice | N | R | sigma | free (T/4) | trip 1 | trip 2 | trip 5 | trip 10 | growth exp. | eps_0 trip 1 | eps_0 trip 10 |')
    print('|---|---|---|---|---|---|---|---|---|---|---|---|')
    for N in Ns:
        for lat in LAT:
            r = get(lat, N, '0.5', sg)
            if r is None: continue
            print(f"| {lat} | {N} | {r['R']:.1f} | {r['sigma']:.2f} | {f(r['eps_ang'][1])} | {f(trip(r,1))} | {f(trip(r,2))} | "
                  f"{f(trip(r,5))} | {f(trip(r,10))} | {slope(r):.2f} | {f(trip(r,1,'eps_0'))} | {f(trip(r,10,'eps_0'))} |")
for sg in ['3', 'f0.025']:
    print(f'\n### Co dependence, sigma = {sg}: eps_ang trip 1 / trip 10 / eps_0 trip 10')
    print('| lattice | N | Co = 0.5 | 0.9 Cmax | 0.99 Cmax |')
    print('|---|---|---|---|---|')
    for N in Ns:
        for lat in LAT:
            cells = []
            for co in ['0.5', 'r0.9', 'r0.99']:
                r = get(lat, N, co, sg)
                cells.append('-' if r is None else f"{f(trip(r,1))} / {f(trip(r,10))} / {f(trip(r,10,'eps_0'))} (Co {r['Co']:.3f})")
            print(f'| {lat} | {N} | ' + ' | '.join(cells) + ' |')
print('\n### which m carry it: fraction of the m != 0 energy at trip 10 (Co 0.5) in m%12==0 | m%4 only | m%6 only | other; top-5 m (<=64)')
for sg in ['3', 'f0.025']:
    for N in Ns:
        for lat in LAT:
            r = get(lat, N, '0.5', sg)
            if r is None: continue
            c = np.array(r['cls'][-1]); c = c / c.sum()
            Em = np.array(r['Em'][-1]); top = np.argsort(Em[1:])[::-1][:5] + 1
            print(f"{sg:7s} {lat} N={N}: " + ' '.join(f'{x:.3f}' for x in c) + '  top m: ' + ','.join(map(str, top)))
